package pl.zagranietyper.service;
import pl.zagranietyper.fixture.ApiFootballClient;import pl.zagranietyper.model.FootballFixtureEventsSnapshot;import pl.zagranietyper.repository.FootballFixtureEventsRepository;
public final class FootballFixtureEventsIngestionService {private final ApiFootballClient client;private final FootballFixtureEventsRepository repository;private final FootballFixtureEventsNormalizer normalizer;public FootballFixtureEventsIngestionService(ApiFootballClient client,FootballFixtureEventsRepository repository,FootballFixtureEventsNormalizer normalizer){this.client=client;this.repository=repository;this.normalizer=normalizer;}public FootballFixtureEventsSnapshot inspect(long fixtureId){return normalizer.normalize(client.fetchFixtureEvents(fixtureId));}public FootballFixtureEventsSnapshot ingest(long fixtureId){var s=inspect(fixtureId);repository.store(s);return s;}}
